// Package ratelimit provides a concurrency-safe token-bucket rate limiter
// with an injectable clock for deterministic testing.
package ratelimit

import (
	"context"
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time so tests can use a fake clock.
type Clock interface {
	Now() time.Time
}

// realClock is the default Clock backed by the standard library.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a token-bucket rate limiter. It is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	clock    Clock
	rate     float64       // tokens per second
	burst    float64       // bucket capacity
	tokens   float64       // current tokens
	last     time.Time     // last refill time
	reserveC chan struct{} // capacity 1; serializes reservations
}

// New creates a Limiter allowing `rate` tokens per second with a
// maximum burst of `burst` tokens. It returns an error if rate or burst
// is non-positive, non-finite, or if clock is nil.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if math.IsNaN(rate) || math.IsInf(rate, 0) || rate <= 0 {
		return nil, errors.New("ratelimit: rate must be a positive finite number")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be positive")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		clock:    clock,
		rate:     rate,
		burst:    float64(burst),
		tokens:   float64(burst),
		last:     clock.Now(),
		reserveC: make(chan struct{}, 1),
	}, nil
}

// NewDefault creates a Limiter using the system clock.
func NewDefault(rate float64, burst int) (*Limiter, error) {
	return New(rate, burst, realClock{})
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// It returns false immediately if n exceeds the bucket capacity or if
// insufficient tokens are currently available.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 || float64(n) > l.burst {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	if l.tokens < float64(n) {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// ReserveN returns a Reservation for n tokens. Callers must invoke
// either Wait or Cancel on the reservation. Reservations are processed
// in arrival order.
func (l *Limiter) ReserveN(ctx context.Context, n int) *Reservation {
	r := &Reservation{lim: l, n: n}
	if n <= 0 || float64(n) > l.burst {
		r.err = errors.New("ratelimit: n out of range")
		r.ok = true // no waiting needed; error is final
		return r
	}
	l.mu.Lock()
	l.refill()
	need := float64(n) - l.tokens
	if need <= 0 {
		l.tokens -= float64(n)
		r.readyAt = l.clock.Now()
		r.ok = true
		l.mu.Unlock()
		return r
	}
	l.tokens = 0 // tokens are pre-consumed by the reservation
	r.readyAt = l.last.Add(time.Duration(need / l.rate * float64(time.Second)))
	r.ok = true
	l.mu.Unlock()
	return r
}

// refill advances the bucket to the current time. Caller must hold mu.
func (l *Limiter) refill() {
	now := l.clock.Now()
	if now.After(l.last) {
		l.tokens = math.Min(l.burst, l.tokens+now.Sub(l.last).Seconds()*l.rate)
		l.last = now
	}
}

// Reservation represents a future token grant.
type Reservation struct {
	lim    *Limiter
	n      int
	readyAt time.Time
	ok     bool
	err    error
	used   bool
}

// OK reports whether the reservation is valid (not an error).
func (r *Reservation) OK() bool { return r.ok && r.err == nil }

// Err returns the error, if any, associated with the reservation.
func (r *Reservation) Err() error { return r.err }

// Wait blocks until the reservation is ready or ctx is done.
func (r *Reservation) Wait(ctx context.Context) error {
	if r.err != nil {
		return r.err
	}
	if !r.ok {
		return errors.New("ratelimit: invalid reservation")
	}
	r.used = true
	delay := time.Until(r.readyAt)
	if c, ok := r.lim.clock.(interface{ Now() time.Time }); ok {
		_ = c
	}
	if delay <= 0 {
		return nil
	}
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-timer.C:
		return nil
	case <-ctx.Done():
		r.Cancel()
		return ctx.Err()
	}
}

// Cancel returns reserved tokens to the bucket, if unused.
func (r *Reservation) Cancel() {
	if r == nil || r.err != nil || !r.ok || r.used {
		return
	}
	r.used = true
	r.lim.mu.Lock()
	defer r.lim.mu.Unlock()
	r.lim.refill()
	r.lim.tokens = math.Min(r.lim.burst, r.lim.tokens+float64(r.n))
}
