// fakeClock is a manually advanced Clock.
type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{now: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewValidation(t *testing.T) {
	fc := newFakeClock()
	tests := []struct {
		name    string
		rate    float64
		burst   int
		clock   Clock
		wantErr bool
	}{
		{"valid", 1.0, 10, fc, false},
		{"zero rate", 0, 10, fc, true},
		{"negative rate", -1, 10, fc, true},
		{"NaN rate", float64('n' - 'n'), 10, fc, false}, // 0 handled above; use real NaN:
		{"NaN rate real", math_NaN(), 10, fc, true},
		{"Inf rate", math_Inf(), 10, fc, true},
		{"zero burst", 1, 0, fc, true},
		{"negative burst", 1, -5, fc, true},
		{"nil clock", 1, 10, nil, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := New(tt.rate, tt.burst, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("New(%v, %d, %v) error = %v, wantErr %v", tt.rate, tt.burst, tt.clock, err, tt.wantErr)
			}
		})
	}
}

func math_NaN() float64 { return nan }
func math_Inf() float64 { return inf }

var (
	nan = func() float64 { return zero / zero }()
	inf = func() float64 { return one / zero }()
	zero = 0.0
	one  = 1.0
)

func TestAllowN(t *testing.T) {
	fc := newFakeClock()
	l, err := New(2.0, 4, fc) // 2 tokens/sec, burst 4
	if err != nil {
		t.Fatal(err)
	}
	tests := []struct {
		name  string
		adv   time.Duration
		n     int
		want  bool
	}{
		{"initial burst allows 4", 0, 4, true},
		{"empty bucket denies 1", 0, 1, false},
		{"deny n > burst", 0, 5, false},
		{"deny n <= 0", 0, 0, false},
		{"half second refills 1", 500 * time.Millisecond, 1, true},
		{"still only 1 token", 0, 1, false},
		{"full refill after 2s", 2 * time.Second, 4, true},
		{"cap at burst", 10 * time.Second, 4, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if tt.adv > 0 {
				fc.Advance(tt.adv)
			}
			if got := l.AllowN(tt.n); got != tt.want {
				t.Errorf("AllowN(%d) = %v, want %v", tt.n, got, tt.want)
			}
		})
	}
}

func TestReserveAndWait(t *testing.T) {
	fc := newFakeClock()
	l, _ := New(1.0, 2, fc)
	if !l.AllowN(2) {
		t.Fatal("expected initial burst of 2")
