// Package ratelimit provides a concurrency-safe token-bucket rate limiter
// with an injectable clock for deterministic testing.
package ratelimit

import (
	"context"
	"errors"
	"sync"
	"time"
)

// Clock abstracts time so tests can use a fake clock.
type Clock interface {
	Now() time.Time
}

// realClock is the default Clock backed by the standard library.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a token-bucket rate limiter. It is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	rate     float64       // tokens per second
	burst    float64       // bucket capacity
	tokens   float64       // current tokens
	last     time.Time     // last refill time
	clock    Clock
}

// Options configures a Limiter.
type Options struct {
	Rate  float64       // tokens added per second; must be > 0
	Burst int           // bucket capacity; must be > 0
	Clock Clock         // optional; defaults to system clock
}

// ErrInvalidConfig is returned by New for invalid parameters.
var ErrInvalidConfig = errors.New("ratelimit: rate must be > 0 and burst must be > 0")

// New creates a Limiter. The bucket starts full.
func New(opts Options) (*Limiter, error) {
	if opts.Rate <= 0 || opts.Burst <= 0 {
		return nil, ErrInvalidConfig
	}
	c := opts.Clock
	if c == nil {
		c = realClock{}
	}
	return &Limiter{
		rate:   opts.Rate,
		burst:  float64(opts.Burst),
		tokens: float64(opts.Burst),
		last:   c.Now(),
		clock:  c,
	}, nil
}

// refill adds tokens accrued since the last call. Caller must hold mu.
func (l *Limiter) refill(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
	l.last = now
}

// Allow reports whether a single token is available, consuming it if so.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// It returns false if n exceeds the bucket's burst capacity.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	if float64(n) > l.burst || float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Wait blocks until n tokens are available, ctx cancellation, or if n
// exceeds burst capacity (in which case it returns immediately).
func (l *Limiter) Wait(ctx context.Context, n int) error {
	if n <= 0 {
		return ctx.Err()
	}
	for {
		l.mu.Lock()
		l.refill(l.clock.Now())
		if float64(n) <= l.burst && float64(n) <= l.tokens {
			l.tokens -= float64(n)
			l.mu.Unlock()
			return nil
		}
		// Compute wait time until enough tokens exist.
		needed := float64(n) - l.tokens
		wait := time.Duration(needed / l.rate * float64(time.Second))
		if float64(n) > l.burst {
			l.mu.Unlock()
			return errors.New("ratelimit: request exceeds burst capacity")
		}
		l.mu.Unlock()

		if wait <= 0 {
			wait = time.Millisecond
		}
		timer := time.NewTimer(wait)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
	}
}

// Tokens returns the current token count without consuming any.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
