	"testing"
	"time"
)

// fakeClock is a manually advanced Clock.
type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{now: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func newLimiter(t *testing.T, rate float64, burst int, clk Clock) *Limiter {
	t.Helper()
	l, err := New(Options{Rate: rate, Burst: burst, Clock: clk})
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}
	return l
}

func TestNewValidation(t *testing.T) {
	tests := []struct {
		name    string
		opts    Options
		wantErr bool
	}{
		{"zero rate", Options{Rate: 0, Burst: 10}, true},
		{"negative rate", Options{Rate: -1, Burst: 10}, true},
		{"zero burst", Options{Rate: 1, Burst: 0}, true},
		{"negative burst", Options{Rate: 1, Burst: -5}, true},
		{"valid", Options{Rate: 1, Burst: 1}, false},
		{"valid with clock", Options{Rate: 5, Burst: 3, Clock: newFakeClock()}, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := New(tt.opts)
			if (err != nil) != tt.wantErr {
				t.Fatalf("New() error = %v, wantErr %v", err, tt.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	clk := newFakeClock()
	// Rate: 1 token/sec, burst 5.
	l := newLimiter(t, 1, 5, clk)

	tests := []struct {
		name  string
		adv   time.Duration // advance clock before call
		n     int
		want  bool
	}{
		{"initial full bucket allows burst", 0, 5, true},
		{"empty bucket denies 1", 0, 1, false},
		{"deny n exceeding burst", 0, 6, false},
		{"one second refills one token", time.Second, 1, true},
		{"second token not yet available", 0, 1, false},
		{"half second not enough", 500 * time.Millisecond, 1, false},
		{"another half second suffices", 500 * time.Millisecond, 1, true},
		{"zero n always allowed", 0, 0, true},
		{"negative n allowed", 0, -3, true},
		{"partial refill capped at burst", 10 * time.Second, 5, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if tt.adv > 0 {
				clk.Advance(tt.adv)
			}
			if got := l.AllowN(tt.n); got != tt.want {
				t.Errorf("AllowN(%d) = %v, want %v", tt.n, got, tt.want)
			}
		})
	}
}

func TestTokens(t *testing.T) {
	clk := newFakeClock()
	l := newLimiter(t, 2, 4, clk) // 2 tokens/sec, burst 4.

	if got := l.Tokens(); got != 4 {
		t.Errorf("Tokens() = %v, want 4", got)
	}
	if !l.AllowN(3) {
		t.Fatal("AllowN(3) = false, want true")
	}
	if got := l.Tokens(); got != 1 {
		t.Errorf("Tokens() = %v, want 1", got)
	}
	clk.Advance(1500 * time.Millisecond) // +3 tokens, capped at 4.
	if got := l.Tokens(); got != 4 {
		t.Errorf("Tokens() = %v, want 4 (capped)", got)
	}
}

func TestWait(t *testing.T) {
	clk := newFakeClock()
	l := newLimiter(t, 1, 2, clk)

	if !l.AllowN(2) {
		t.Fatal("AllowN(2) = false, want true")
	}

	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()
	if err := l.Wait(ctx, 1); err != nil {
		t.Fatalf("Wait() error = %v, want nil", err)
	}

	if err := l.Wait(ctx, 3); err == nil {
		t.Fatal("Wait(3) = nil, want error (exceeds burst)")
	}

	ctx2, cancel2 := context.WithCancel(context.Background())
	cancel2()
	if err := l.Wait(ctx2, 1); err == nil {
		t.Fatal("Wait with canceled ctx = nil, want error")
	}
}

func TestConcurrentAccess(t *testing.T) {
	clk := newFakeClock()
	l := newLimiter(t, 1000, 100, clk)

	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.AllowN(1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	mu.Lock()
	defer mu.Unlock()
	if allowed != 100 {
		t.Errorf("allowed = %d, want 100", allowed)
	}
	if l.AllowN(1) {
		t.Error("AllowN after exhaustion = true, want false")
	}
}
