// Package ratelimit provides a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"context"
	"errors"
	"sync"
	"time"
)

// Clock abstracts time so tests can use a fake clock.
type Clock interface {
	Now() time.Time
	Since(time.Time) time.Duration
}

// realClock is the default Clock backed by the standard library.
type realClock struct{}

func (realClock) Now() time.Time                { return time.Now() }
func (realClock) Since(t time.Time) time.Duration { return time.Since(t) }

// Limiter is a token-bucket rate limiter. It is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	rate     float64       // tokens per second
	burst    float64       // bucket capacity
	tokens   float64       // current tokens
	last     time.Time     // last refill time
	clock    Clock
}

// Options configures a Limiter.
type Options struct {
	Rate  float64       // tokens per second; must be > 0
	Burst float64       // bucket capacity; must be > 0 and >= Rate is not required
	Clock Clock         // optional; defaults to real time
}

// ErrInvalidConfig is returned by New for invalid parameters.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be positive")

// New creates a Limiter. rate is tokens/second; burst is bucket capacity.
// The bucket starts full.
func New(rate, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: burst,
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// n must be >= 1; n > burst always fails.
func (l *Limiter) AllowN(n float64) bool {
	if n <= 0 || n > l.burst {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	if l.tokens >= n {
		l.tokens -= n
		return true
	}
	return false
}

// AllowWait blocks until n tokens are available or ctx is done.
func (l *Limiter) AllowWait(ctx context.Context, n float64) bool {
	for {
		if l.AllowN(n) {
			return true
		}
		if ctx.Err() != nil {
			return false
		}
		// Sleep a small quantum; a production version could compute
		// the exact wait time from the deficit.
		select {
		case <-ctx.Done():
			return false
		case <-time.After(time.Millisecond):
		}
	}
}

// refill adds tokens accrued since the last call, capped at burst.
// Caller must hold l.mu.
func (l *Limiter) refill() {
	now := l.clock.Now()
	elapsed := now.Sub(l.last)
	if elapsed <= 0 {
		return
	}
	l.tokens = min(l.burst, l.tokens+float64(elapsed)*l.rate/float64(time.Second))
	l.last = now
}

// Tokens returns the current token count (without consuming).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
