// Package ratelimit provides a concurrency-safe token-bucket rate limiter
// with an injectable clock for deterministic testing.
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time so tests can use a fake implementation.
type Clock interface {
	Now() time.Time
}

// realClock is the default Clock backed by the standard library.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a token-bucket rate limiter. It is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	clock    Clock
	rate     float64       // tokens per second
	capacity float64       // maximum burst size
	tokens   float64       // current tokens
	last     time.Time     // last refill time
}

// Config validates and constructs a Limiter.
type Config struct {
	Rate     float64       // sustained token refill rate (tokens/second); must be > 0
	Capacity float64       // bucket capacity (burst size); must be > 0
	Clock    Clock         // optional; defaults to real time
}

// New creates a Limiter. The bucket starts full.
func New(cfg Config) (*Limiter, error) {
	if cfg.Rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if cfg.Capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be > 0")
	}
	clk := cfg.Clock
	if clk == nil {
		clk = realClock{}
	}
	now := clk.Now()
	return &Limiter{
		clock:    clk,
		rate:     cfg.Rate,
		capacity: cfg.Capacity,
		tokens:   cfg.Capacity,
		last:     now,
	}, nil
}

// refill adds tokens accrued since the last call. Caller must hold mu.
func (l *Limiter) refill(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.tokens = min(l.capacity, l.tokens+elapsed*l.rate)
	l.last = now
}

// Allow reports whether a single token is available, consuming it if so.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN attempts to consume n tokens atomically. It returns true and
// consumes the tokens if available; otherwise it returns false and
// consumes nothing. n must be >= 1 and <= capacity.
func (l *Limiter) AllowN(n float64) bool {
	ok, _ := l.allowN(n)
	return ok
}

// allowN returns availability and the time until n tokens would be
// available (zero if allowed now).
func (l *Limiter) allowN(n float64) (bool, time.Duration) {
	if n < 1 {
		n = 1 // treat non-positive as a single token
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.refill(now)
	if l.tokens >= n {
		l.tokens -= n
		return true, 0
	}
	deficit := n - l.tokens
	return false, time.Duration(deficit / l.rate * float64(time.Second))
}

// TryAllowN consumes n tokens if available; otherwise it returns the
// duration to wait until they would be (without consuming anything).
func (l *Limiter) TryAllowN(n float64) (bool, time.Duration) {
	if n > l.capacity {
		return false, 0 // can never succeed
	}
	return l.allowN(n)
}

// Tokens returns the current token count without consuming any.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

func (l *Limiter) String() string {
	return fmt.Sprintf("ratelimit.Limiter{rate:%.4f, capacity:%.4f}", l.rate, l.capacity)
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
