// Package ratelimit provides a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"context"
	"errors"
	"sync"
	"time"
)

// Clock abstracts time so tests can use a fake clock.
type Clock interface {
	Now() time.Time
	Sleep(d time.Duration)
}

// realClock is the default Clock backed by the standard library.
type realClock struct{}

func (realClock) Now() time.Time          { return time.Now() }
func (realClock) Sleep(d time.Duration)  { time.Sleep(d) }

// RealClock returns a Clock backed by the standard library.
func RealClock() Clock { return realClock{} }

// Limiter is a token-bucket rate limiter. It is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	rate     float64       // tokens per second
	burst    float64       // bucket capacity
	tokens   float64       // current tokens
	last     time.Time     // last refill time
	clock    Clock
}

// Options configures a Limiter.
type Options struct {
	Rate  float64       // tokens per second; must be > 0
	Burst float64       // bucket capacity; must be > 0 and >= Rate is not required
	Clock Clock         // optional; defaults to RealClock()
}

// ErrInvalidConfig is returned by New for invalid parameters.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be positive")

// New creates a Limiter. rate is tokens/second; burst is bucket capacity.
// The bucket starts full.
func New(rate, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = RealClock()
	}
	now := clock.Now()
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: burst,
		last:   now,
		clock:  clock,
	}, nil
}

// NewWithOpts creates a Limiter from Options.
func NewWithOpts(o Options) (*Limiter, error) {
	return New(o.Rate, o.Burst, o.Clock)
}

// refill adds tokens accrued since last, capped at burst.
// Caller must hold mu.
func (l *Limiter) refill(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
	l.last = now
}

// Allow reports whether one token is available, consuming it if so.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// It returns false if n exceeds the bucket capacity.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	if float64(n) > l.burst || float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// AllowWait blocks until n tokens are available, ctx permitting.
// It returns ctx.Err() if the context is done first.
func (l *Limiter) AllowWait(ctx context.Context, n int) error {
	if n <= 0 {
		return nil
	}
	if float64(n) > l.burst {
		return errors.New("ratelimit: n exceeds burst capacity")
	}
	for {
		l.mu.Lock()
		l.refill(l.clock.Now())
		if float64(n) <= l.tokens {
			l.tokens -= float64(n)
			l.mu.Unlock()
			return nil
		}
		deficit := float64(n) - l.tokens
		wait := time.Duration(deficit / l.rate * float64(time.Second))
		l.mu.Unlock()

		if wait <= 0 {
			wait = time.Millisecond
		}
		timer := time.NewTimer(wait)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
	}
}

// Tokens returns the current token count without consuming any.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

// Burst returns the bucket capacity.
func (l *Limiter) Burst() float64 { return l.burst }

// Rate returns the refill rate in tokens per second.
func (l *Limiter) Rate() float64 { return l.rate }

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
